package io.knowledgebrain.gateway;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class RubricGradingProxyTest {
 String id="01a10000-0000-7000-8000-000000000000",base="/api/groups/"+id+"/studies/"+id+"/assignments/"+id+"/submissions/"+id+"/rubric-grade";
 @Test void gradeWriteForwardsIndependentCasAndCookieWithoutCallerActor()throws Exception{var f=new GroupProxyTest();f.init();var r=f.request("PUT",base);r.addHeader("If-Match","\"sg0\"");r.addHeader("Authorization","Bearer spoof");r.addHeader("X-Principal-Id",id);r.setContentType("application/json");r.setContent("{\"assignmentVersion\":1,\"criteria\":[]}".getBytes());f.proxy.proxy(r);verify(f.transport).send(eq(new GatewayRoute("collaboration",base)),eq("PUT"),argThat(h->h.entrySet().stream().filter(e->e.getKey().equalsIgnoreCase("If-Match")).findFirst().orElseThrow().getValue().getFirst().equals("\"sg0\"")&&!h.containsKey("Authorization")&&!h.containsKey("X-Principal-Id")),eq(r.getContentAsByteArray()));}
 @Test void immutableBasisReadsRejectQueriesAndBodies()throws Exception{var f=new GroupProxyTest();f.init();String path=base.replace("/rubric-grade","/grade/revisions/1/rubric-assessment");f.proxy.proxy(f.request("GET",path));verify(f.transport).send(eq(new GatewayRoute("collaboration",path)),eq("GET"),any(),any());var r=f.request("GET",path);r.setQueryString("actorId="+id);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(r));var body=f.request("GET",path);body.setContent("{}".getBytes());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(body));}
}
